import stepsData from "./wati-bot-steps.json";

/**
 * Works out where a person is in the WhatsApp chatbot from WATI's chat history.
 *
 * Pure functions only (no network, no database), so they can be tested on sample histories.
 * Step fingerprints are generated by scripts/build-wati-flow.mjs from the same text WATI sends.
 */

export type BotStage = "browse" | "signup" | "done";

export interface BotStep {
  key: string;
  label: string;
  stage: BotStage;
  order: number;
  nodeId: string;
  fingerprint: string;
}

export const BOT_STEPS: BotStep[] = stepsData as BotStep[];
const STEP_BY_KEY = new Map(BOT_STEPS.map((step) => [step.key, step]));
const STEP_BY_NODE = new Map(BOT_STEPS.map((step) => [step.nodeId, step]));

export function getBotStep(key: string): BotStep | undefined {
  return STEP_BY_KEY.get(key);
}

export function getBotStepByNodeId(nodeId: string | null | undefined): BotStep | undefined {
  return nodeId ? STEP_BY_NODE.get(nodeId) : undefined;
}

export function normalizeForMatch(text: string): string {
  return text.toLowerCase().replace(/[^a-z0-9]/g, "");
}

/** The bot step a message from the business is, or null for anything else (fallback texts, agents). */
export function matchBotStep(text: string): BotStep | null {
  const normalized = normalizeForMatch(text);
  if (!normalized) return null;
  return BOT_STEPS.find((step) => normalized.includes(step.fingerprint)) || null;
}

export interface ChatEvent {
  at: Date;
  /** true for anything the business number sent (bot, agent or template). */
  fromBusiness: boolean;
  text: string;
}

export interface SignupAnswers {
  name?: string;
  email?: string;
  state?: string;
  parties?: string;
  speedPost?: string;
}

const ANSWER_FOR_STEP: Record<string, keyof SignupAnswers> = {
  S1: "name",
  S2: "email",
  S3: "state",
  S4: "parties",
  S5: "speedPost",
};

export interface BotConfirmation {
  at: Date;
  /**
   * The details the person confirmed. Read from the bot's own "Please check your details"
   * message when it can be parsed, since that is exactly what WATI stored and the person said yes
   * to; otherwise worked out from the replies.
   */
  answers: SignupAnswers;
  source: "summary" | "replies";
}

export interface BotProgress {
  /** First bot message of the latest visit (a new visit starts at the welcome message). */
  visitStartedAt: Date | null;
  lastActivityAt: Date | null;
  /** Step the person was last sent. */
  currentStep: BotStep | null;
  currentStepAt: Date | null;
  /** Steps sent during the latest visit, in order, without repeats. */
  stepsSeen: { key: string; at: Date }[];
  /** Answers given so far in the latest sign-up attempt. */
  answers: SignupAnswers;
  /** Latest "Yes, send my link" tap, with the answers it confirmed. */
  lastConfirmation: BotConfirmation | null;
  /** When the bot last sent the link to /wa/link. */
  linkMessageAt: Date | null;
}

export function isConfirmReply(text: string): boolean {
  return normalizeForMatch(text).startsWith("yessendmylink");
}

const SUMMARY_LABELS: Record<keyof SignupAnswers, string> = {
  name: "Name",
  email: "Email",
  state: "State",
  parties: "Opposite parties",
  speedPost: "Speed Post",
};

/** The five answers from the bot's "Please check your details" message, or null if unreadable. */
export function answersFromSummary(text: string): SignupAnswers | null {
  const answers: SignupAnswers = {};
  for (const [field, label] of Object.entries(SUMMARY_LABELS) as [keyof SignupAnswers, string][]) {
    const match = text.match(new RegExp(`^\\s*${label}:[ \\t]*(.+)$`, "im"));
    if (!match || !match[1].trim()) return null;
    answers[field] = match[1].trim();
  }
  return answers;
}

/** Walks the chat oldest-first. Events must all belong to one WhatsApp number. */
export function analyseChat(events: ChatEvent[]): BotProgress {
  const ordered = [...events].sort((a, b) => a.at.getTime() - b.at.getTime());

  const progress: BotProgress = {
    visitStartedAt: null,
    lastActivityAt: ordered.length ? ordered[ordered.length - 1].at : null,
    currentStep: null,
    currentStepAt: null,
    stepsSeen: [],
    answers: {},
    lastConfirmation: null,
    linkMessageAt: null,
  };
  let confirmText = "";

  for (const event of ordered) {
    if (event.fromBusiness) {
      const step = matchBotStep(event.text);
      if (!step) continue; // validation retries, fallback reminders, agents

      if (step.key === "WELCOME") {
        progress.visitStartedAt = event.at;
        progress.stepsSeen = [];
      }
      if (step.key === "S1") progress.answers = {}; // a new sign-up attempt, incl. "Start again"
      if (step.key === "S6") confirmText = event.text;
      if (step.key === "LINK") progress.linkMessageAt = event.at;
      if (!progress.visitStartedAt) progress.visitStartedAt = event.at;

      progress.currentStep = step;
      progress.currentStepAt = event.at;
      if (!progress.stepsSeen.some((seen) => seen.key === step.key)) {
        progress.stepsSeen.push({ key: step.key, at: event.at });
      }
      continue;
    }

    // A reply from the person, which answers the step they were last sent
    const current = progress.currentStep?.key;
    if (!current) continue;
    const answerKey = ANSWER_FOR_STEP[current];
    if (answerKey) {
      // The last reply wins, so a valid answer after a validation retry replaces the invalid one
      progress.answers[answerKey] = event.text;
    } else if (current === "S6" && isConfirmReply(event.text)) {
      // WATI can apply quickly typed replies to a later question, so the replies alone may not match
      // what it stored; its own summary is what the person actually confirmed
      const summary = answersFromSummary(confirmText);
      progress.lastConfirmation = summary
        ? { at: event.at, answers: summary, source: "summary" }
        : { at: event.at, answers: { ...progress.answers }, source: "replies" };
    }
  }

  return progress;
}

export const SIGNUP_FIELDS: (keyof SignupAnswers)[] = ["name", "email", "state", "parties", "speedPost"];

export function hasAllAnswers(answers: SignupAnswers): boolean {
  return SIGNUP_FIELDS.every((field) => Boolean(answers[field]?.trim()));
}
